alter table public.wallets enable row level security;
alter table public.transfers enable row level security;

create policy wallets_select on public.wallets for select using (user_id = auth.uid());
create policy wallets_update on public.wallets for update using (user_id = auth.uid());

create policy transfers_select on public.transfers for select using (from_user = auth.uid() or to_user = auth.uid());
create policy transfers_insert on public.transfers for insert with check (from_user = auth.uid());

create or replace function public.send_points(p_to uuid, p_amount integer) returns bigint as $$
declare
  v_caller_id uuid;
  v_balance integer;
  v_recipient_balance integer;
  v_transfer_id bigint;
begin
  if auth.role() != 'authenticated' then
    raise exception 'User not authenticated';
  end if;

  v_caller_id := auth.uid();

  if p_amount <= 0 then
    raise exception 'Amount must be positive';
  end if;

  select balance into v_balance from wallets where user_id = v_caller_id;
  if not found then
    raise exception 'Caller has no wallet';
  end if;

  select balance into v_recipient_balance from wallets where user_id = p_to;
  if not found then
    raise exception 'Recipient has no wallet';
  end if;

  if p_to = v_caller_id then
    raise exception 'Cannot send to self';
  end if;

  if v_balance < p_amount then
    raise exception 'Insufficient balance';
  end if;

  update wallets set balance = balance - p_amount where user_id = v_caller_id;
  update wallets set balance = balance + p_amount where user_id = p_to;

  insert into transfers (from_user, to_user, amount)
  values (v_caller_id, p_to, p_amount)
  returning id into v_transfer_id;

  return v_transfer_id;
end;
$$ language plpgsql security definer;
