create or replace function public.send_points(p_to uuid, p_amount integer) returns bigint as $$
declare
  caller_id uuid;
  current_balance integer;
  transfer_id bigint;
begin
  if auth.uid() is null then
    raise exception 'User not authenticated';
  end if;

  if p_amount <= 0 then
    raise exception 'Amount must be positive';
  end if;

  caller_id := auth.uid();

  select balance into current_balance from public.wallets where user_id = caller_id;
  if current_balance < p_amount then
    raise exception 'Insufficient balance';
  end if;

  if not exists (select 1 from public.wallets where user_id = p_to) then
    raise exception 'Recipient has no wallet';
  end if;

  if caller_id = p_to then
    raise exception 'Cannot send to self';
  end if;

  update public.wallets set balance = balance - p_amount where user_id = caller_id;
  update public.wallets set balance = balance + p_amount where user_id = p_to;

  insert into public.transfers (from_user, to_user, amount) values (caller_id, p_to, p_amount) returning id into transfer_id;

  return transfer_id;
end;
$$ language plpgsql security definer;
