alter table public.api_keys enable row level security;
create function check_revoked_update() returns trigger as $$
begin
  if tg_op = 'update' then
    if (new.key_hash is distinct from old.key_hash or
        new.name is distinct from old.name or
        new.last4 is distinct from old.last4 or
        new.created_at is distinct from old.created_at) then
      raise exception 'Only revoked_at can be updated';
    end if;
    if new.revoked_at is not null and old.revoked_at is null then
      return new;
    else
      raise exception 'revoked_at can only be set once';
    end if;
  end if;
  return new;
end;
