    IF NOT (NEW.revoked_at IS DISTINCT FROM OLD.revoked_at) THEN
      RETURN NEW;
    END IF;
    IF (NEW.key_hash IS DISTINCT FROM OLD.key_hash OR
        NEW.name IS DISTINCT FROM OLD.name OR
        NEW.last4 IS DISTINCT FROM OLD.last4 OR
        NEW.created_at IS DISTINCT FROM OLD.created_at) THEN
      RAISE EXCEPTION 'Cannot update fields other than revoked_at';
    END IF;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

