CREATE OR REPLACE FUNCTION check_event_capacity(event_id bigint) RETURNS boolean AS $$
DECLARE
  current_count integer;
  event_capacity integer;
BEGIN
  SELECT COUNT(*) INTO current_count FROM public.rsvps WHERE event_id = $1;
  SELECT capacity INTO event_capacity FROM public.events WHERE id = $1;
  RETURN current_count < event_capacity;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

