create or replace function enforce_leave_request_update()
returns trigger as $$
begin
  if auth.role() = 'anon' then
    raise exception 'Anonymous users cannot update leave requests.';
  end if;

  if new.status not in ('pending', 'approved', 'rejected', 'cancelled') then
    raise exception 'Invalid status.';
  end if;

  if new.status = 'pending' then
    if new.employee_id != old.employee_id then
      raise exception 'Cannot change employee_id when status is pending.';
    end if;
    if new.starts_on is not null and new.starts_on != old.starts_on then
      raise exception 'Cannot change starts_on when status is pending.';
    end if;
    if new.ends_on is not null and new.ends_on != old.ends_on then
      raise exception 'Cannot change ends_on when status is pending.';
    end if;
    if new.note is not null and new.note != old.note then
      raise exception 'Cannot change note when status is pending.';
    end if;
    if new.decided_by is not null then
      raise exception 'Cannot set decided_by when status is pending.';
    end if;
  elsif new.status = 'approved' or new.status = 'rejected' then
    if new.employee_id != old.employee_id then
      raise exception 'Cannot change employee_id when status is approved or rejected.';
    end if;
    if new.starts_on is not null and new.starts_on != old.starts_on then
      raise exception 'Cannot change starts_on when status is approved or rejected.';
    end if;
    if new.ends_on is not null and new.ends_on != old.ends_on then
      raise exception 'Cannot change ends_on when status is approved or rejected.';
    end if;
    if new.note is not null and new.note != old.note then
      raise exception 'Cannot change note when status is approved or rejected.';
    end if;
    if new.decided_by is null then
      raise exception 'decided_by must be set when status is approved or rejected.';
    end if;
    if new.decided_by != auth.uid() then
      raise exception 'Only the manager can approve or reject a request.';
    end if;
    if not is_manager_of_employee(auth.uid(), new.employee_id) then
      raise exception 'User is not a manager of the employee.';
    end if;
  elsif new.status = 'cancelled' then
    if new.employee_id != old.employee_id then
      raise exception 'Cannot change employee_id when status is cancelled.';
    end if;
    if new.starts_on is not null and new.starts_on != old.starts_on then
      raise exception 'Cannot change starts_on when status is cancelled.';
    end if;
    if new.ends_on is not null and new.ends_on != old.ends_on then
      raise exception 'Cannot change ends_on when status is cancelled.';
    end if;
    if new.note is not null and new.note != old.note then
      raise exception 'Cannot change note when status is cancelled.';
    end if;
    if new.decided_by is not null then
      raise exception 'Cannot set decided_by when status is cancelled.';
    end if;
    if new.employee_id != auth.uid() then
      raise exception 'Only the employee can cancel their own request.';
    end if;
  end if;

  return new;
end;
$$ language plpgsql;

create trigger enforce_leave_request_update_trigger
before update on public.leave_requests
for each row
execute function enforce_leave_request_update();

