create or replace function check_reservation_update() 
returns trigger as $$
begin
  if tg_op = 'update' then
    if new.status = 'cancelled' then
      if new.user_id = auth.uid() and old.status = 'booked' and old.reserved_for > now() then
        return new;
      else
        raise exception 'Permission denied';
      end if;
    elsif new.status in ('seated', 'no_show') then
      if exists (
        select 1 
        from public.restaurant_staff 
        where restaurant_id = new.restaurant_id and user_id = auth.uid()
      ) and old.status = 'booked' and old.reserved_for <= now() then
        return new;
      else
        raise exception 'Permission denied';
      end if;
    else
      raise exception 'Invalid status change';
    end if;
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger reservations_update_trigger
before update on public.reservations
for each row
execute function check_reservation_update();
