create function public.accept_invite(p_token text) returns bigint as $$
declare
  v_invite record;
  v_email text;
begin
  v_email := (select email from auth.jwt()::json)->>'email';
  if v_email is null then
    raise exception 'User not authenticated';
  end if;

  select * into v_invite from public.invites where token = p_token;
  if not found then
    raise exception 'Invite not found';
  end if;

  if now() > v_invite.expires_at then
    raise exception 'Invite expired';
  end if;

  if v_invite.accepted_at is not null then
    raise exception 'Invite already accepted';
  end if;

  if lower(v_invite.email) <> lower(v_email) then
    raise exception 'Email does not match';
  end if;

  insert into public.org_members (org_id, user_id, role)
  values (v_invite.org_id, auth.uid(), v_invite.role);

  update public.invites set accepted_at = now() where token = p_token;
  return v_invite.org_id;
end;
$$ language plpgsql security definer;

