create or replace function public.accept_invite(p_token text)
returns bigint as $$
declare
  v_invite_id invites.token%type;
  v_email text;
  v_user_email text;
  v_org_id invites.org_id%type;
  v_role invites.role%type;
begin
  if auth.role() = 'anon' then
    raise exception 'Not authenticated';
  end if;

  select token, org_id, role, email into v_invite_id, v_org_id, v_role, v_email
  from invites
  where token = p_token;

  if not found then
    raise exception 'Invite not found';
  end if;

  if now() > (select expires_at from invites where token = p_token) then
    raise exception 'Invite expired';
  end if;

  if (select accepted_at from invites where token = p_token) is not null then
    raise exception 'Invite already accepted';
  end if;

  select (auth.jwt() ->> 'email') into v_user_email;
  if lower(v_email) != lower(v_user_email) then
    raise exception 'Email mismatch';
  end if;

  update invites
  set accepted_at = now()
  where token = p_token;

  insert into org_members (org_id, user_id, role)
  values (v_org_id, auth.uid(), v_role);

  return v_org_id;
end;
$$ language plpgsql security definer;

