  user_email := lower((auth.jwt() ->> 'email')::text);

  select * into invite_row from invites where token = p_token;
  if not found then
    raise exception 'Invite not found';
  end if;

  if invite_row.expires_at < now() then
    raise exception 'Invite expired';
  end if;

  if invite_row.accepted_at is not null then
    raise exception 'Invite already accepted';
  end if;

  if lower(invite_row.email) <> user_email then
    raise exception 'Email does not match';
  end if;

  insert into public.org_members (org_id, user_id, role)
  values (invite_row.org_id, auth.uid(), invite_row.role);

  update public.invites set accepted_at = now() where token = p_token;

  return invite_row.org_id;
exception when others then
  if found then
    delete from public.org_members where org_id = invite_row.org_id and user_id = auth.uid();
  end if;
  raise;
end;
$$ language plpgsql security definer;
