  return (select departs_at from public.rides where id = ride_id) > now();
end;
$$ language plpgsql security definer;

create function check_ride_booking_update() returns trigger as $$
declare
  ride_seats integer;
  confirmed_count integer;
begin
  if not exists (select 1 from public.rides where id = new.ride_id and driver_id = auth.uid()) then
    raise exception 'Only the driver can update this booking.';
  end if;
  if (select departs_at from public.rides where id = new.ride_id) <= now() then
    raise exception 'Cannot update booking after departure.';
  end if;
  if new.status not in ('confirmed', 'declined') then
    raise exception 'Invalid status update.';
  end if;
  if new.status = 'confirmed' then
    select seats into ride_seats from public.rides where id = new.ride_id;
    select count(*) into confirmed_count from public.ride_bookings where ride_id = new.ride_id and status = 'confirmed';
    if confirmed_count >= ride_seats then
      raise exception 'Cannot confirm booking: no seats available.';
    end if;
  end if;
  return new;
end;
$$ language plpgsql security definer;

