```sql
create function is_allowed_folder(user_id uuid, folder_id bigint) returns boolean as $$
declare
  current_folder_id bigint := folder_id;
  current_owner uuid;
  current_grant record;
begin
  loop
    select owner_id into current_owner from public.folders where id = current_folder_id;
    if current_owner = user_id then
      return true;
    end if;
    select * into current_grant from public.folder_grants where folder_id = current_folder_id and user_id = user_id;
    if found then
      return true;
    end if;
    select parent_id into current_folder_id from public.folders where id = current_folder_id;
    if current_folder_id is null then
      return false;
    end if;
  end loop;
end;
$$ language plpgsql security definer;

create function is_allowed_edit(user_id uuid, folder_id bigint) returns boolean as $$
declare
  current_folder_id bigint := folder_id;
  current_owner uuid;
  current_grant record;
begin
  loop
    select owner_id into current_owner from public.folders where id = current_folder_id;
    if current_owner = user_id then
      return true;
    end if;
    select * into current_grant from public.folder_grants where folder_id = current_folder_id and user_id = user_id and can_edit = true;
    if found then
      return true;
    end if;
    select parent_id into current_folder_id from public.folders where id = current_folder_id;
    if current_folder_id is null then
      return false;
    end if;
  end loop;
end;
$$ language plpgsql security definer;

create function is_owner_or_granted(user_id uuid, folder_id bigint) returns boolean as $$
declare
  current_folder_id bigint := folder_id;
  current_owner uuid;
  current_grant record;
begin
  loop
    select owner_id into current_owner from public.folders where id = current_folder_id;
    if current_owner = user_id then
      return true;
    end if;
    select * into current_grant from public.folder_grants where folder_id = current_folder_id and user_id = user_id;
    if found then
      return true;
    end if;
    select parent_id into current_folder_id from public.folders where id = current_folder_id;
    if current_folder_id is null then
      return false;
    end if;
  end loop;
end;
$$ language plpgsql security definer;

create function is_owner_or_granted_edit(user_id uuid, folder_id bigint) returns boolean as $$
declare
  current_folder_id bigint := folder_id;
  current_owner uuid;
  current_grant record;
begin
  loop
    select owner_id into current_owner from public.folders where id = current_folder_id;
    if current_owner = user_id then
      return true;
    end if;
    select * into current_grant from public.folder_grants where folder_id = current_folder_id and user_id = user_id and can_edit = true;
    if found then
      return true;
    end if;
    select parent_id into current_folder_id from public.folders where id = current_folder_id;
    if current_folder_id is null then
      return false;
    end if;
  end loop;
end;
$$ language plpgsql security definer;

create policy "Folders: Read if allowed" on public.folders for select using (is_allowed_folder(auth.uid(), id));

create policy "Folders: Insert if owner" on public.folders for insert with check (owner_id = auth.uid() and parent_id is null or (parent_id is not null and exists (select 1 from public.folders where id = parent_id and owner_id = auth.uid())));

create policy "Folders: Update if allowed" on public.folders for update using (is_owner_or_granted(auth.uid(), id));

create policy "Folders: Delete if allowed" on public.folders for delete using (is_owner_or_granted(auth.uid(), id));

create policy "Folder Grants: Read if owner or granted" on public.folder_grants for select using (exists (select 1 from public.folders where id = folder_id and (owner_id = auth.uid() or exists (select 1 from public.folder_grants where folder_id = public.folders.id and user_id = auth.uid()))) or exists (select 1 from public.folders where id = folder_id and owner_id = auth.uid()));

create policy "Folder Grants: Insert if allowed" on public.folder_grants for insert with check (exists (select 1 from public.folders where id = folder_id and (owner_id = auth.uid() or exists (select 1 from public.folder_grants where folder_id = public.folders.id and user_id = auth.uid()))));

create policy "Folder Grants: Update if allowed" on public.folder_grants for update using (exists (select 1 from public.folders where id = folder_id and (owner_id = auth.uid() or exists (select 1 from public.folder_grants where folder_id = public.folders.id and user_id = auth.uid()))));

create policy "Folder Grants: Delete if allowed" on public.folder_grants for delete using (exists (select 1 from public.folders where id = folder_id and (owner_id = auth.uid() or exists (select 1 from public.folder_grants where folder_id = public.folders.id and user_id = auth.uid()))));

