create or replace function has_folder_access(folder_id bigint, user_id uuid)
returns boolean as $$
declare
    current_folder_id bigint := folder_id;
    current_owner uuid;
    has_grant bool;
begin
    -- Check if user is owner of current folder
    select owner_id into current_owner from folders where id = current_folder_id;
    if current_owner = user_id then
        return true;
    end if;

    -- Check if user has grant on current folder
    select exists (select 1 from folder_grants where folder_id = current_folder_id and user_id = user_id and can_edit) into has_grant;
    if has_grant then
        return true;
    end if;

    -- Traverse up the hierarchy
    while current_folder_id is not null loop
        select parent_id into current_folder_id from folders where id = current_folder_id;
        if current_folder_id is null then
            break;
        end if;

        -- Check owner of current folder
        select owner_id into current_owner from folders where id = current_folder_id;
        if current_owner = user_id then
            return true;
        end if;

        -- Check grant on current folder
        select exists (select 1 from folder_grants where folder_id = current_folder_id and user_id = user_id and can_edit) into has_grant;
        if has_grant then
            return true;
        end if;
    end loop;

    return false;
end;
$$ language plpgsql;

create or replace function has_folder_edit_access(folder_id bigint, user_id uuid)
returns boolean as $$
declare
    current_folder_id bigint := folder_id;
    current_owner uuid;
    has_edit bool;
begin
    -- Check if user is owner of current folder
    select owner_id into current_owner from folders where id = current_folder_id;
    if current_owner = user_id then
        return true;
    end if;

    -- Check if user has edit grant on current folder
    select exists (select 1 from folder_grants where folder_id = current_folder_id and user_id = user_id and can_edit) into has_edit;
    if has_edit then
        return true;
    end if;

    -- Traverse up the hierarchy
    while current_folder_id is not null loop
        select parent_id into current_folder_id from folders where id = current_folder_id;
        if current_folder_id is null then
            break;
        end if;

        -- Check owner of current folder
        select owner_id into current_owner from folders where id = current_folder_id;
        if current_owner = user_id then
            return true;
        end if;

        -- Check edit grant on current folder
        select exists (select 1 from folder_grants where folder_id = current_folder_id and user_id = user_id and can_edit) into has_edit;
        if has_edit then
            return true;
        end if;
    end loop;

    return false;
end;
$$ language plpgsql;

