alter table public.ops_team enable row level security;
alter table public.access_requests enable row level security;
alter table public.access_approvals enable row level security;

create function public.is_ops_team_member(uid uuid) returns boolean as $$
  select exists(select 1 from public.ops_team where user_id = uid);
$$ language sql;

create policy ops_team_select on public.ops_team for select to authenticated using (true);

create policy access_requests_insert on public.access_requests for insert to authenticated with check (true);
create policy access_requests_select on public.access_requests for select to authenticated using (requester_id = auth.uid() or exists (select 1 from public.ops_team where user_id = auth.uid()));
create policy access_requests_delete on public.access_requests for delete to authenticated using (requester_id = auth.uid() and status = 'pending');

create policy access_approvals_select on public.access_approvals for select to authenticated using (exists (select 1 from public.access_requests ar where ar.id = public.access_approvals.request_id and ar.requester_id = auth.uid()) or exists (select 1 from public.ops_team where user_id = auth.uid()));
create policy access_approvals_insert on public.access_approvals for insert to authenticated using (false);
create policy access_approvals_update on public.access_approvals for update to authenticated using (false);
create policy access_approvals_delete on public.access_approvals for delete to authenticated using (false);

create or replace function public.approve_access(p_request_id bigint) returns text as $$
declare
  v_requester_id uuid;
  v_approver_id uuid := auth.uid();
  v_status text;
  v_approved_count int;
begin
  if not public.is_ops_team_member(v_approver_id) then
    raise exception 'User is not on the ops team';
  end if;

  select requester_id, status into v_requester_id, v_status
  from public.access_requests
  where id = p_request_id;

  if not found then
    raise exception 'Request not found';
  end if;

  if v_status != 'pending' then
    raise exception 'Request is not pending';
  end if;

  if v_requester_id = v_approver_id then
    raise exception 'User cannot approve their own request';
  end if;

  if exists (select 1 from public.access_approvals where request_id = p_request_id and approver_id = v_approver_id) then
    raise exception 'User has already approved this request';
  end if;

  insert into public.access_approvals (request_id, approver_id) values (p_request_id, v_approver_id);

  select count(*) into v_approved_count
  from public.access_approvals
  where request_id = p_request_id;

  if v_approved_count = 2 then
    update public.access_requests set status = 'granted' where id = p_request_id;
    v_status := 'granted';
  else
    v_status := 'pending';
  end if;

  return v_status;
end;
$$ language plpgsql security definer;

grant execute on function public.approve_access to authenticated;
