create function is_team_member(team_id bigint) returns boolean as $$
begin
  return exists (
    select 1
    from team_members
    where team_id = $1 and user_id = auth.uid()
  );
end;
$$ language plpgsql security definer;

create function is_judge(team_id bigint) returns boolean as $$
declare
  event_id bigint;
begin
  select t.event_id into event_id
  from teams t
  where t.id = team_id;
  return exists (
    select 1
    from judges
    where event_id = event_id and user_id = auth.uid()
  );
end;
$$ language plpgsql security definer;

create function is_deadline_passed(team_id bigint) returns boolean as $$
declare
  event_deadline timestamptz;
begin
  select e.deadline into event_deadline
  from teams t
  join events e on t.event_id = e.id
  where t.id = team_id;
  return event_deadline <= now();
end;
$$ language plpgsql security definer;

create policy submissions_select on public.submissions for select to authenticated using (
  is_team_member(team_id) or (is_judge(team_id) and is_deadline_passed(team_id))
);

