create function is_pharmacist() returns boolean as $$
begin
  return exists (select 1 from public.pharmacists where user_id = auth.uid());
end;
$$ language plpgsql security definer;

create policy pharmacists_select on public.pharmacists for select using (auth.role() = 'authenticated');
create policy pharmacists_insert on public.pharmacists for insert with check (auth.role() = 'service_role');
create policy pharmacists_update on public.pharmacists for update with check (auth.role() = 'service_role');
create policy pharmacists_delete on public.pharmacists for delete with check (auth.role() = 'service_role');

create policy prescriptions_select on public.prescriptions for select using (
  patient_id = auth.uid() or is_pharmacist()
);
create policy prescriptions_insert on public.prescriptions for insert with check (auth.role() = 'service_role');
create policy prescriptions_update on public.prescriptions for update with check (auth.role() = 'service_role');
create policy prescriptions_delete on public.prescriptions for delete with check (auth.role() = 'service_role');

create policy dispenses_select on public.dispenses for select using (
  exists (select 1 from public.prescriptions p where p.id = prescription_id and p.patient_id = auth.uid()) or is_pharmacist()
);
create policy dispenses_insert on public.dispenses for insert with check (auth.role() = 'service_role');
create policy dispenses_update on public.dispenses for update with check (auth.role() = 'service_role');
create policy dispenses_delete on public.dispenses for delete with check (auth.role() = 'service_role');

create or replace function public.dispense(p_prescription_id bigint) returns integer as $$
declare
  v_refills_left integer;
  v_patient_id uuid;
  v_expires_at timestamptz;
begin
  if not is_pharmacist() then
    raise exception 'User is not a pharmacist';
  end if;

  select refills_left, patient_id, expires_at into v_refills_left, v_patient_id, v_expires_at
  from prescriptions
  where id = p_prescription_id;

  if not found then
    raise exception 'Prescription not found';
  end if;

  if v_expires_at < now() then
    raise exception 'Prescription has expired';
  end if;

  if v_refills_left <= 0 then
    raise exception 'No refills left';
  end if;

  if v_patient_id = auth.uid() then
    raise exception 'Cannot dispense own prescription';
  end if;

  update prescriptions set refills_left = refills_left - 1 where id = p_prescription_id;
  insert into dispenses (prescription_id, pharmacist_id) values (p_prescription_id, auth.uid());

  return v_refills_left - 1;
end;
$$ language plpgsql security definer;
