create policy dispenses_delete on public.dispenses for delete with check (auth.role() = 'service_role');

create or replace function public.dispense(p_prescription_id bigint) returns integer as $$
declare
  v_refills_left integer;
  v_patient_id uuid;
  v_pharmacist_id uuid;
begin
  select user_id into v_pharmacist_id from public.pharmacists where user_id = auth.uid();
  if not found then
    raise exception 'Caller is not a pharmacist';
  end if;

  select refills_left, patient_id into v_refills_left, v_patient_id
  from public.prescriptions
  where id = p_prescription_id;

  if not found then
    raise exception 'Prescription does not exist';
  end if;

  if (select expires_at from public.prescriptions where id = p_prescription_id) <= now() then
    raise exception 'Prescription has expired';
  end if;

  if v_refills_left <= 0 then
    raise exception 'No refills left';
  end if;

  if v_patient_id = auth.uid() then
    raise exception 'Cannot dispense own prescription';
