create function check_request_update()
returns trigger as $$
begin
  if tg_op = 'update' then
    if new.status is distinct from old.status then
      if new.unit_id is distinct from old.unit_id then
        raise exception 'Cannot update unit_id';
      end if;
      if new.created_by is distinct from old.created_by then
        raise exception 'Cannot update created_by';
      end if;
      if new.description is distinct from old.description then
        raise exception 'Cannot update description';
      end if;
      return new;
    else
      raise exception 'No changes allowed except status';
    end if;
  end if;
  return new;
end;
$$ language plpgsql;

