alter table public.courses enable row level security;
alter table public.enrollments enable row level security;
alter table public.threads enable row level security;
alter table public.posts enable row level security;

create or replace function is_ta_in_course(thread_id bigint) returns boolean as $$
declare
  course_id bigint;
begin
  select course_id into course_id from threads where id = thread_id;
  return exists (
    select 1 from enrollments 
    where course_id = course_id 
    and user_id = auth.uid() 
    and role = 'ta'
  );
end;
$$ language plpgsql;

create policy enrollments_select on public.enrollments for select using (user_id = auth.uid());

create policy threads_insert on public.threads for insert with check (
  exists (select 1 from enrollments where user_id = auth.uid() and course_id = new.course_id)
  and new.is_locked = false
);

create policy threads_update_lock on public.threads for update using (
  is_ta_in_course(old.id)
);

create policy threads_select on public.threads for select using (
  exists (
    select 1 from enrollments 
    where user_id = auth.uid() 
    and course_id = threads.course_id
  )
);

create policy posts_select on public.posts for select using (
  exists (
    select 1 from threads t 
    join enrollments e on t.course_id = e.course_id 
    where e.user_id = auth.uid() and t.id = posts.thread_id
  )
);

create policy posts_insert on public.posts for insert with check (
  exists (
    select 1 from threads t 
    join enrollments e on t.course_id = e.course_id 
    where e.user_id = auth.uid() and t.id = new.thread_id and t.is_locked = false
  )
);

create policy posts_update on public.posts for update using (
  (
    author_id = auth.uid() 
    and (select is_locked from threads where id = posts.thread_id) = false
  ) or is_ta_in_course(posts.thread_id)
);

create policy posts_delete on public.posts for delete using (
  (
    author_id = auth.uid() 
    and (select is_locked from threads where id = posts.thread_id) = false
  ) or is_ta_in_course(posts.thread_id)
);
