CREATE OR REPLACE FUNCTION is_enrolled(course_id bigint) RETURNS boolean AS $$
SELECT EXISTS (
  SELECT 1
  FROM enrollments
  WHERE enrollments.course_id = course_id
  AND enrollments.user_id = auth.uid()
);
$$ LANGUAGE sql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION is_ta(course_id bigint) RETURNS boolean AS $$
SELECT EXISTS (
  SELECT 1
  FROM enrollments
  WHERE enrollments.course_id = course_id
  AND enrollments.user_id = auth.uid()
  AND enrollments.role = 'ta'
);
$$ LANGUAGE sql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION is_allowed_to_view_post(thread_id bigint) RETURNS boolean AS $$
SELECT is_enrolled((SELECT course_id FROM threads WHERE id = thread_id));
$$ LANGUAGE sql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION is_thread_unlocked(thread_id bigint) RETURNS boolean AS $$
SELECT is_locked = false FROM threads WHERE id = thread_id;
$$ LANGUAGE sql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION is_ta_in_thread(thread_id bigint) RETURNS boolean AS $$
SELECT is_ta((SELECT course_id FROM threads WHERE id = thread_id));
$$ LANGUAGE sql SECURITY DEFINER;

