create function check_item_status_update() returns trigger as $$
begin
  if new.status = 'claimed' then
    if (select count(*) from claims where item_id = new.id and status = 'approved') > 0 then
      raise exception 'Item already has an approved claim';
    end if;
  end if;
  return new;
end;
$$ language plpgsql;

create trigger enforce_item_status_update before update on public.items for each row execute procedure check_item_status_update();

create function check_claim_update() returns trigger as $$
begin
  if tg_op = 'update' then
    if old.status != 'pending' then
      raise exception 'Only pending claims can be updated';
    end if;
    if new.status is distinct from old.status then
      if new.status not in ('approved', 'rejected') then
        raise exception 'Status can only be approved or rejected';
      end if;
    end if;
    if new.claimant_id != old.claimant_id or new.message != old.message or new.item_id != old.item_id then
      raise exception 'Claimant cannot change any fields except status';
    end if;
  end if;
  return new;
end;
$$ language plpgsql;

create trigger enforce_claim_update before update on public.claims for each row execute procedure check_claim_update();
