create or replace function is_trip_date_valid(driver_id uuid, vehicle_id bigint, trip_date date)
returns boolean as $$
begin
  return exists (
    select 1
    from public.assignments
    where assignments.driver_id = driver_id
      and assignments.vehicle_id = vehicle_id
      and assignments.starts_on <= trip_date
      and assignments.ends_on >= trip_date
  );
end;
$$ language plpgsql security definer;

create or replace function check_trip_date()
returns trigger as $$
begin
  if not is_trip_date_valid(new.driver_id, new.vehicle_id, new.trip_date) then
    raise exception 'Trip date is not covered by any assignment for the driver and vehicle.';
  end if;
  return new;
end;
$$ language plpgsql security definer;

