create function public.mark_shipped(p_order_id bigint) returns text
  language plpgsql
  as $$
declare
  v_order public.orders;
  v_new_status text := 'shipped';
begin
  select * into v_order from public.orders where id = p_order_id;
  if not found then
    raise exception 'Order does not exist';
  end if;

  if v_order.seller_id != auth.uid() then
    raise exception 'Only the seller can mark an order as shipped';
  end if;

  if v_order.status != 'paid' then
    raise exception 'Order must be in "paid" status to be marked as shipped';
  end if;

  update public.orders set status = v_new_status where id = p_order_id;
  return v_new_status;
end;
$$;

create function public.release_funds(p_order_id bigint) returns text
  language plpgsql
  as $$
declare
  v_order public.orders;
  v_new_status text := 'released';
begin
  select * into v_order from public.orders where id = p_order_id;
  if not found then
    raise exception 'Order does not exist';
  end if;

  if v_order.buyer_id != auth.uid() then
    raise exception 'Only the buyer can release funds';
  end if;

  if v_order.status != 'shipped' then
    raise exception 'Order must be in "shipped" status to be released';
  end if;

  update public.orders set status = v_new_status where id = p_order_id;
  return v_new_status;
end;
$$;

create function public.refund_order(p_order_id bigint) returns text
  language plpgsql
  as $$
declare
  v_order public.orders;
  v_new_status text := 'refunded';
begin
  select * into v_order from public.orders where id = p_order_id;
  if not found then
    raise exception 'Order does not exist';
  end if;

  if v_order.seller_id != auth.uid() then
    raise exception 'Only the seller can refund an order';
  end if;

  if v_order.status not in ('paid', 'shipped') then
    raise exception 'Order must be in "paid" or "shipped" status to be refunded';
  end if;

  update public.orders set status = v_new_status where id = p_order_id;
  return v_new_status;
end;
$$;
