create policy "No direct deletes" on public.orders for delete using (false);

create or replace function public.mark_shipped(p_order_id bigint) returns text as $$
begin
  if not exists (select 1 from public.orders where id = p_order_id) then
    raise exception 'Order does not exist';
  end if;
  if (select seller_id from public.orders where id = p_order_id) != auth.uid() then
    raise exception 'Caller is not the seller';
  end if;
  if (select status from public.orders where id = p_order_id) not in ('paid') then
    raise exception 'Order not in valid state';
  end if;
  update public.orders set status = 'shipped' where id = p_order_id;
  return 'shipped';
end;
$$ language plpgsql security definer;

create or replace function public.release_funds(p_order_id bigint) returns text as $$
begin
  if not exists (select 1 from public.orders where id = p_order_id) then
    raise exception 'Order does not exist';
  end if;
  if (select buyer_id from public.orders where id = p_order_id) != auth.uid() then
    raise exception 'Caller is not the buyer';
  end if;
  if (select status from public.orders where id = p_order_id) not in ('shipped') then
    raise exception 'Order not in valid state';
  end if;
  update public.orders set status = 'released' where id = p_order_id;
  return 'released';
end;
$$ language plpgsql security definer;

create or replace function public.refund_order(p_order_id bigint) returns text as $$
begin
  if not exists (select 1 from public.orders where id = p_order_id) then
    raise exception 'Order does not exist';
  end if;
  if (select seller_id from public.orders where id = p_order_id) != auth.uid() then
    raise exception 'Caller is not the seller';
  end if;
  if (select status from public.orders where id = p_order_id) not in ('paid', 'shipped') then
    raise exception 'Order not in valid state';
  end if;
  update public.orders set status = 'refunded' where id = p_order_id;
  return 'refunded';
end;
$$ language plpgsql security definer;

grant execute on function public.mark_shipped(p_order_id bigint) to authenticated;
grant execute on function public.release_funds(p_order_id bigint) to authenticated;
grant execute on function public.refund_order(p_order_id bigint) to authenticated;
