begin
  if (new.status = 'reviewed' and old.status != 'reviewed') then
    if not exists (select 1 from public.translators where translators.project_id = new.project_id and translators.user_id = auth.uid() and translators.lang = new.lang and translators.role = 'reviewer') then
      raise exception 'Only reviewers can mark segments as reviewed';
    end if;
  end if;
  if new.status = 'reviewed' then
    if new.target_text is not null and new.target_text != old.target_text then
      raise exception 'Reviewed segments cannot be modified';
    end if;
    if new.source_text is not null and new.source_text != old.source_text then
      raise exception 'Source text cannot be modified';
    end if;
  end if;
  if new.status != 'reviewed' and new.translated_by is not null and new.translated_by != auth.uid() then
    raise exception 'Only the translator can update the segment';
  end if;
  return new;
end;
$$ language plpgsql;

