CREATE OR REPLACE FUNCTION enforce_chore_approval()
RETURNS TRIGGER AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.status = 'approved' THEN
      IF NOT EXISTS (SELECT 1 FROM household_members WHERE household_id = NEW.household_id AND user_id = auth.uid() AND role = 'parent') THEN
        RAISE EXCEPTION 'Only parents can approve chores.';
      END IF;
      IF OLD.status != 'done' THEN
        RAISE EXCEPTION 'Chore can only be approved if it was done.';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE TRIGGER enforce_chore_approval_trigger
BEFORE UPDATE ON public.chores
FOR EACH ROW
EXECUTE FUNCTION enforce_chore_approval();

REVOKE ALL ON public.households FROM anon;
REVOKE ALL ON public.household_members FROM anon;
REVOKE ALL ON public.chores FROM anon;
