CREATE OR REPLACE FUNCTION public.place_bid(p_auction_id bigint, p_amount numeric)
RETURNS numeric AS $$
DECLARE
  v_auction auctions%ROWTYPE;
  v_bidder_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'User not authenticated';
  END IF;
  v_bidder_id := auth.uid();
  SELECT * INTO v_auction FROM auctions WHERE id = p_auction_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Auction not found';
  END IF;
  IF v_auction.ends_at < now() THEN
    RAISE EXCEPTION 'Auction has ended';
  END IF;
  IF v_auction.seller_id = v_bidder_id THEN
    RAISE EXCEPTION 'Seller cannot bid on their own auction';
  END IF;
  IF v_auction.highest_bid IS NULL THEN
    IF p_amount < v_auction.starting_price THEN
      RAISE EXCEPTION 'Amount too low: must be at least starting price';
    END IF;
  ELSE
    IF p_amount < (v_auction.highest_bid + v_auction.min_increment) THEN
      RAISE EXCEPTION 'Amount too low: must be at least highest bid + min increment';
    END IF;
  END IF;
  INSERT INTO bids (auction_id, bidder_id, amount, placed_at)
  VALUES (p_auction_id, v_bidder_id, p_amount, now());
  UPDATE auctions
  SET highest_bid = p_amount,
      highest_bidder = v_bidder_id
  WHERE id = p_auction_id;
  RETURN p_amount;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
