for select
using (envelope_id in (select id from public.envelopes where sender_id = auth.uid() or exists (select 1 from public.envelope_recipients where envelope_recipients.envelope_id = envelopes.id and envelope_recipients.user_id = auth.uid())));

create or replace function public.sign_envelope(p_envelope_id bigint) returns text as $$
declare
  v_status envelopes.status%type;
  v_signed bool;
  v_earlier_signed bool;
  v_all_signed bool;
begin
  select status into v_status from public.envelopes where id = p_envelope_id;
  if v_status is null then
    raise exception 'Envelope does not exist';
  end if;
  if v_status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;
  select exists (select 1 from public.envelope_recipients where envelope_id = p_envelope_id and user_id = auth.uid()) into v_signed;
  if not v_signed then
    raise exception 'Caller is not a recipient of the envelope';
  end if;
  select exists (select 1 from public.envelope_recipients where envelope_id = p_envelope_id and user_id = auth.uid() and signed_at is not null) into v_signed;
  if v_signed then
    raise exception 'Caller has already signed the envelope';
  end if;
  select exists (select 1 from public.envelope_recipients where envelope_id = p_envelope_id and sign_order < (select sign_order from public.envelope_recipients where envelope_id = p_envelope_id and user_id = auth.uid()) and signed_at is null) into v_earlier_signed;
  if v_earlier_signed then
    raise exception 'An earlier recipient has not signed the envelope';
  end if;
  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = auth.uid();
  select count(*) = (select count(*) from public.envelope_recipients where envelope_id = p_envelope_id and signed_at is not null) into v_all_signed;
  if v_all_signed then
    update public.envelopes set status = 'completed' where id = p_envelope_id;
    return 'completed';
  else
    return 'sent';
  end if;
end;
$$ language plpgsql security definer;

create or replace function public.void_envelope(p_envelope_id bigint) returns text as $$
declare
  v_status envelopes.status%type;
  v_sender bool;
begin
  select status into v_status from public.envelopes where id = p_envelope_id;
  if v_status is null then
    raise exception 'Envelope does not exist';
  end if;
  if v_status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;
  select sender_id = auth.uid() into v_sender from public.envelopes where id = p_envelope_id;
  if not v_sender then
    raise exception 'Only the sender can void an envelope';
  end if;
  update public.envelopes set status = 'voided' where id = p_envelope_id;
  return 'voided';
end;
$$ language plpgsql security definer;

revoke all on public.envelopes from public;
revoke all on public.envelope_recipients from public;
grant select on public.envelopes to authenticated;
grant select on public.envelope_recipients to authenticated;
