create or replace function public.sign_envelope(p_envelope_id bigint) returns text as $$
declare
    v_status envelopes.status%type;
    v_sign_order envelope_recipients.sign_order%type;
    v_prev_signed_count integer;
begin
    select status into v_status from envelopes where id = p_envelope_id;
    if not found then raise exception 'Envelope not found';
    end if;
    if v_status != 'sent' then raise exception 'Envelope is not in sent status';
    end if;

    select sign_order into v_sign_order from envelope_recipients where envelope_id = p_envelope_id and user_id = auth.uid();
    if not found then raise exception 'User is not a recipient of this envelope';
    end if;

    if (select signed_at from envelope_recipients where envelope_id = p_envelope_id and user_id = auth.uid()) is not null then
        raise exception 'User has already signed this envelope';
    end if;

    select count(*) into v_prev_signed_count
    from envelope_recipients
    where envelope_id = p_envelope_id
      and sign_order < v_sign_order
      and signed_at is not null;
    if v_prev_signed_count < v_sign_order - 1 then
        raise exception 'Not all previous signers have signed';
    end if;

    update envelope_recipients
    set signed_at = now()
    where envelope_id = p_envelope_id and user_id = auth.uid();

    if (select count(*) from envelope_recipients where envelope_id = p_envelope_id and signed_at is not null) = (select count(*) from envelope_recipients where envelope_id = p_envelope_id) then
        update envelopes set status = 'completed' where id = p_envelope_id;
    end if;

    return (select status from envelopes where id = p_envelope_id);
end;
$$ language plpgsql security definer;

