declare
    v_sender_id envelopes.sender_id%type;
    v_status envelopes.status%type;
begin
    select sender_id, status into v_sender_id, v_status from envelopes where id = p_envelope_id;
    if not found then raise exception 'Envelope not found';
    end if;
    if v_status != 'sent' then raise exception 'Envelope is not in sent status';
    end if;
    if auth.uid() != v_sender_id then raise exception 'Only the sender can void the envelope';
    end if;

