create or replace function public.sign_envelope(p_envelope_id bigint) returns text as $$
declare
  v_sender_id uuid;
  v_status text;
  v_sign_order int;
  v_has_signed boolean;
  v_all_previous_signed boolean;
  v_recipient_count int;
  v_signed_count int;
  v_result text;
begin
  select sender_id, status into v_sender_id, v_status
  from public.envelopes where id = p_envelope_id;
  if not found then raise exception 'Envelope not found';
  end if;
  if v_status != 'sent' then raise exception 'Envelope is not in sent status';
  end if;

  select sign_order into v_sign_order
  from public.envelope_recipients
  where envelope_id = p_envelope_id and user_id = auth.uid();
  if not found then raise exception 'User is not a recipient of this envelope';
  end if;

  select signed_at is not null into v_has_signed
  from public.envelope_recipients
  where envelope_id = p_envelope_id and user_id = auth.uid();
  if v_has_signed then raise exception 'User has already signed this envelope';
  end if;

  select count(*) into v_signed_count
  from public.envelope_recipients
  where envelope_id = p_envelope_id and signed_at is not null and sign_order < v_sign_order;
  select count(*) into v_recipient_count
  from public.envelope_recipients
  where envelope_id = p_envelope_id and sign_order < v_sign_order;
  if v_signed_count != v_recipient_count then raise exception 'Not all previous signers have signed';
  end if;

  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = auth.uid();

  select count(*) into v_signed_count
  from public.envelope_recipients
  where envelope_id = p_envelope_id and signed_at is not null;
  select count(*) into v_recipient_count
  from public.envelope_recipients
  where envelope_id = p_envelope_id;
  if v_signed_count = v_recipient_count then
    update public.envelopes set status = 'completed' where id = p_envelope_id;
    v_result := 'completed';
  else
    v_result := 'sent';
  end if;
  return v_result;
end;
$$ language plpgsql security definer;

create or replace function public.void_envelope(p_envelope_id bigint) returns text as $$
declare
  v_sender_id uuid;
  v_status text;
  v_result text;
begin
  select sender_id, status into v_sender_id, v_status
  from public.envelopes where id = p_envelope_id;
  if not found then raise exception 'Envelope not found';
  end if;
  if v_status != 'sent' then raise exception 'Envelope is not in sent status';
  end if;
  if v_sender_id != auth.uid() then raise exception 'Only the sender can void the envelope';
  end if;
  update public.envelopes set status = 'voided' where id = p_envelope_id;
  v_result := 'voided';
  return v_result;
end;
$$ language plpgsql security definer;

grant execute on function public.sign_envelope(bigint) to authenticated;
grant execute on function public.void_envelope(bigint) to authenticated;
