    raise exception 'Earlier signers have not signed yet';
  end if;
  update envelope_recipients set signed_at = now() where envelope_id = p_envelope_id and user_id = auth.uid();
  if (select count(*) from envelope_recipients where envelope_id = p_envelope_id and signed_at is null) = 0 then
    update envelopes set status = 'completed' where id = p_envelope_id;
  end if;
  return (select status from envelopes where id = p_envelope_id);
