create or replace function public.sign_envelope(p_envelope_id bigint) returns text as $$
declare
  v_user_id uuid;
  v_status text;
  v_current_sign_order integer;
  v_prev_unsigned_count integer;
  v_total_recipients integer;
  v_signed_recipients integer;
begin
  select user_id into v_user_id from envelope_recipients where envelope_id = p_envelope_id and user_id = auth.uid();
  if not found then
    raise exception 'User is not a recipient of this envelope';
