  select sign_order into v_current_sign_order from envelope_recipients where envelope_id = p_envelope_id and user_id = auth.uid();

  select count(*) into v_prev_unsigned_count
  from envelope_recipients er
  where er.envelope_id = p_envelope_id and er.sign_order < v_current_sign_order and er.signed_at is null;
  if v_prev_unsigned_count > 0 then
    raise exception 'Not all previous signers have signed';
