  update envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = auth.uid();

  select count(*) into v_total_recipients from envelope_recipients where envelope_id = p_envelope_id;
  select count(*) into v_signed_recipients from envelope_recipients where envelope_id = p_envelope_id and signed_at is not null;

  if v_signed_recipients = v_total_recipients then
    update envelopes set status = 'completed' where id = p_envelope_id;
    v_status := 'completed';
  else
    v_status := 'sent';
  end if;

  return v_status;
end;
$$ language plpgsql;

