create policy jobs_select on public.jobs for select using (
  auth.role() = 'authenticated' and (
    customer_id = auth.uid() or exists (select 1 from public.mechanics where user_id = auth.uid() and garage_id = garage_id)
  )
);

create policy jobs_insert on public.jobs for insert with check (
  auth.role() = 'authenticated' and exists (select 1 from public.mechanics where user_id = auth.uid() and garage_id = garage_id)
);

create policy jobs_update on public.jobs for update using (auth.role() = 'authenticated');
create policy jobs_delete on public.jobs for delete using (auth.role() = 'service_role');

create function check_job_update() returns trigger as $$
begin
  if (TG_OP = 'UPDATE') then
    if (auth.role() != 'authenticated') then
      raise exception 'Unauthorized';
    end if;

    if (new.status = 'approved') then
      if (new.customer_id != auth.uid()) then
        raise exception 'Only customer can approve job';
      end if;
      if (new.quote_amount != old.quote_amount or new.vehicle != old.vehicle or new.garage_id != old.garage_id) then
        raise exception 'Cannot change fields other than status when approving';
      end if;
    elsif (new.status in ('in_progress', 'done')) then
      if (not exists (select 1 from public.mechanics where user_id = auth.uid() and garage_id = new.garage_id)) then
        raise exception 'Only mechanics can update to in_progress or done';
      end if;
      if (new.quote_amount != old.quote_amount) then
        raise exception 'Cannot change quote_amount after approval';
      end if;
    elsif (old.status = 'quoted' and new.status = 'quoted') then
      if (not exists (select 1 from public.mechanics where user_id = auth.uid() and garage_id = new.garage_id)) then
        raise exception 'Only mechanics can update quoted jobs';
      end if;
    else
      raise exception 'Invalid status transition';
    end if;
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger jobs_update_trigger before update on public.jobs for each row execute procedure check_job_update();
