create policy jobs_select on public.jobs for select using (
  (customer_id = auth.uid() AND auth.role() = 'authenticated') OR
  (exists (select 1 from public.mechanics where user_id = auth.uid() and garage_id = garage_id))
);

create policy jobs_insert on public.jobs for insert with check (
  status = 'quoted' AND
  garage_id IN (SELECT garage_id FROM public.mechanics WHERE user_id = auth.uid())
);

create policy jobs_update on public.jobs for update using (
  (customer_id = auth.uid() AND status = 'quoted') OR
  (exists (select 1 from public.mechanics where user_id = auth.uid() and garage_id = garage_id) AND (status = 'quoted' OR status = 'approved' OR status = 'in_progress'))
);

create or replace function check_job_update() returns trigger as $$
begin
  if tg_op = 'update' then
    if new.garage_id != old.garage_id then
      raise exception 'Cannot change garage_id';
    end if;

    if new.customer_id = auth.uid() then
      if old.status = 'quoted' and new.status = 'approved' then
        if new.quote_amount != old.quote_amount then
          raise exception 'Customer cannot change quote_amount';
        end if;
        if new.vehicle != old.vehicle then
          raise exception 'Customer cannot change vehicle';
        end if;
      else
        if new.status != old.status then
          raise exception 'Customer can only approve a quoted job';
        end if;
      end if;
    else
      if not exists (select 1 from public.mechanics where user_id = auth.uid() and garage_id = new.garage_id) then
        raise exception 'User is not a mechanic of this garage';
      end if;

      if old.status = 'quoted' then
        if new.quote_amount != old.quote_amount then
          if new.status != old.status then
            raise exception 'Mechanic can only change quote_amount when status is quoted';
          end if;
          if new.vehicle != old.vehicle then
            raise exception 'Mechanic cannot change vehicle';
          end if;
          if new.customer_id != old.customer_id then
            raise exception 'Mechanic cannot change customer_id';
          end if;
        else
          if new.status != old.status then
            raise exception 'Mechanic cannot change status when job is quoted';
          end if;
          if new.vehicle != old.vehicle then
            raise exception 'Mechanic cannot change vehicle';
          end if;
          if new.customer_id != old.customer_id then
            raise exception 'Mechanic cannot change customer_id';
          end if;
        end if;
      elsif old.status = 'approved' then
        if new.status not in ('in_progress', 'done') then
          raise exception 'Mechanic can only move approved jobs to in_progress or done';
        end if;
        if new.quote_amount != old.quote_amount then
          raise exception 'Mechanic cannot change quote_amount';
        end if;
        if new.vehicle != old.vehicle then
          raise exception 'Mechanic cannot change vehicle';
        end if;
        if new.customer_id != old.customer_id then
          raise exception 'Mechanic cannot change customer_id';
        end if;
      elsif old.status = 'in_progress' then
        if new.status != 'done' then
          raise exception 'Mechanic can only move in_progress jobs to done';
        end if;
        if new.quote_amount != old.quote_amount then
          raise exception 'Mechanic cannot change quote_amount';
        end if;
        if new.vehicle != old.vehicle then
          raise exception 'Mechanic cannot change vehicle';
        end if;
        if new.customer_id != old.customer_id then
          raise exception 'Mechanic cannot change customer_id';
        end if;
      else
        raise exception 'Invalid status transition';
      end if;
    end if;
  end if;
  return new;
end;
$$ language plpgsql;

create trigger jobs_update_check before update on public.jobs for each row execute function check_job_update();
```

