create function is_eligible_for_booking(desk_id bigint, user_id uuid, day date) returns boolean as $$
declare
  user_tier text;
  desk_zone text;
  valid_until date;
begin
  select tier into user_tier from memberships where user_id = user_id;
  select zone into desk_zone from desks where id = desk_id;
  select valid_until into valid_until from memberships where user_id = user_id;

  if user_tier is null then
    return false;
  end if;

  if desk_zone = 'premium' and user_tier != 'premium' then
    return false;
  end if;

  if day > valid_until then
    return false;
  end if;

  if day < current_date then
    return false;
  end if;

  return true;
end;
$$ language plpgsql;

create policy bookings_insert on public.bookings for insert to authenticated with check (is_eligible_for_booking(desk_id, user_id, day));
create policy bookings_delete on public.bookings for delete to authenticated using (user_id = auth.uid() and day >= current_date);

create function check_max_bookings() returns trigger as $$
declare
  count integer;
begin
  select count(*) into count from bookings where user_id = new.user_id and day >= current_date;
  if count >= 3 then
    raise exception 'User already has 3 or more upcoming bookings.';
  end if;
  return new;
end;
$$ language plpgsql;

create trigger check_max_bookings_trigger before insert on public.bookings for each row execute function check_max_bookings();
