create or replace function check_shopping_item_update()
returns trigger as $$
begin
  if tg_op = 'update' then
    if new.added_by = auth.uid() and new.is_bought = false then
      if old.claimed_by is distinct from new.claimed_by or old.is_bought is distinct from new.is_bought then
        if new.is_bought = true then
          if new.claimed_by != auth.uid() then
            raise exception 'Only the claimed_by can mark an item as bought.';
          end if;
        end if;
      else
        raise exception 'Only claimed_by and is_bought can be updated.';
      end if;
    else
      if new.claimed_by = auth.uid() or old.claimed_by = auth.uid() then
        if new.claimed_by is null and old.claimed_by = auth.uid() then
          return new;
        elsif new.is_bought = true and old.is_bought = false and new.claimed_by = auth.uid() then
          return new;
        else
          raise exception 'Invalid update to shopping_item.';
        end if;
      else
        raise exception 'User is not the claimed_by or added_by for this update.';
      end if;
    end if;
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger shopping_items_update_check
before update on public.shopping_items
for each row
execute function check_shopping_item_update();

