    raise exception 'Referral code does not exist';
  end if;

  if v_referrer_id = auth.uid() then
    raise exception 'Cannot redeem own referral code';
  end if;

  if exists (select 1 from referrals where referee_id = auth.uid()) then
    raise exception 'User has already redeemed a referral code';
  end if;

  select count(*) into v_referral_count from referrals where referrer_id = v_referrer_id;
  if v_referral_count >= 5 then
    raise exception 'Referrer has reached referral limit';
  end if;

  insert into referrals (referrer_id, referee_id, created_at)
  values (v_referrer_id, auth.uid(), now())
  returning id into v_referee_id;

  insert into credits (user_id, amount, reason)
  values (auth.uid(), 100, 'referral_redeemed');

  insert into credits (user_id, amount, reason)
  values (v_referrer_id, 100, 'referral_reward');

  return v_referee_id;
end;
