create function check_enrollment_capacity() returns trigger as $$
declare
  current_enrolled_count integer;
  class_capacity integer;
begin
  if new.status = 'enrolled' then
    select count(*) into current_enrolled_count
    from public.class_spots
    where class_id = new.class_id and status = 'enrolled';

    select capacity into class_capacity
    from public.classes
    where id = new.class_id;

    if current_enrolled_count >= class_capacity then
      raise exception 'Class is full. Cannot enroll.';
    end if;
  end if;
  return new;
end;
$$ language plpgsql security definer;

