  enrolled_count integer;
  capacity integer;
begin
  select count(*) into enrolled_count from class_spots where class_id = $1 and status = 'enrolled';
  select capacity into capacity from classes where id = $1;
  if status = 'enrolled' then
    return enrolled_count < capacity;
  else
    return true;
  end if;
end;
