      if not exists (select 1 from public.hoa_admins where user_id = auth.uid()) then
        raise exception 'Only HOA admins can revoke permits.';
      end if;
    elsif (not new.revoked and old.revoked) then
      raise exception 'Cannot un-revoke a permit.';
    elsif (new.plate is not null and new.plate <> old.plate) then
      if not exists (select 1 from public.residents where user_id = auth.uid() and unit_id = new.unit_id) then
        raise exception 'Only residents of the unit can update plate.';
      end if;
    elsif (new.valid_until is not null and new.valid_until <> old.valid_until) then
      raise exception 'Residents cannot change permit validity.';
    end if;
  end if;
  return new;
end;
