create or replace function public.is_clinician() returns boolean as $$
begin
  return exists (select 1 from public.clinicians where user_id = auth.uid());
end;
$$ language plpgsql security definer;

create or replace function public.is_auditor() returns boolean as $$
begin
  return exists (select 1 from public.auditors where user_id = auth.uid());
end;
$$ language plpgsql security definer;

create or replace function public.has_break_glass_grant(p_patient_id bigint) returns boolean as $$
declare
  v_grant record;
begin
  select * into v_grant
  from public.break_glass_grants
  where clinician_id = auth.uid() and patient_id = p_patient_id and expires_at > now();
  return found;
end;
$$ language plpgsql security definer;

create or replace function public.break_glass(p_patient_id bigint, p_reason text) returns timestamptz as $$
declare
  v_patient patients%rowtype;
  v_clinician boolean;
  v_reason_trimmed text;
  v_expires_at timestamptz;
begin
  v_reason_trimmed := trim(p_reason);
  if length(v_reason_trimmed) < 10 then
    raise exception 'Reason must be at least 10 characters long.';
  end if;

  v_clinician := public.is_clinician();
  if not v_clinician then
    raise exception 'Only clinicians can break glass.';
  end if;

  select * into v_patient from public.patients where id = p_patient_id;
  if not found then
    raise exception 'Patient does not exist.';
  end if;

  v_expires_at := now() + interval '1 hour';

  insert into public.break_glass_grants (patient_id, clinician_id, reason, expires_at)
  values (p_patient_id, auth.uid(), p_reason, v_expires_at);

  return v_expires_at;
end;
$$ language plpgsql security definer;

