for select
using (
  exists (
    select 1
    from public.care_team
    where care_team.patient_id = medical_records.patient_id
      and care_team.clinician_id = auth.uid()
  )
  or public.has_break_glass_grant(medical_records.patient_id)
);

create policy "Clinicians can see their own break_glass grants" on public.break_glass_grants
for select
using (clinician_id = auth.uid());

create policy "Auditors can see all break_glass grants" on public.break_glass_grants
for select
using (public.is_auditor());

