create or replace function public.transfer_stock(p_from bigint, p_to bigint, p_sku text, p_qty integer) returns integer as $$
declare
    v_moved_by uuid := auth.uid();
    v_current_qty integer;
    v_exists boolean;
begin
    if not exists (select 1 from public.warehouse_staff where warehouse_id = p_from and user_id = v_moved_by) then
        raise exception 'Not staff of source warehouse';
    end if;

    if p_qty <= 0 then
        raise exception 'Quantity must be positive';
    end if;

    if p_from = p_to then
        raise exception 'Source and destination cannot be the same';
    end if;

    if not exists (select 1 from public.warehouses where id = p_to) then
        raise exception 'Destination warehouse does not exist';
    end if;

    select qty into v_current_qty from public.stock where warehouse_id = p_from and sku = p_sku;
    if not found then
        raise exception 'Source warehouse has no stock for SKU';
    end if;

    if v_current_qty < p_qty then
        raise exception 'Not enough stock in source warehouse';
    end if;

    update public.stock set qty = qty - p_qty where warehouse_id = p_from and sku = p_sku;
    get diagnostics v_current_qty = row_count;

    select exists (select 1 from public.stock where warehouse_id = p_to and sku = p_sku) into v_exists;
    if not v_exists then
        insert into public.stock (warehouse_id, sku, qty) values (p_to, p_sku, p_qty);
    else
        update public.stock set qty = qty + p_qty where warehouse_id = p_to and sku = p_sku;
    end if;

    insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by, moved_at)
    values (p_from, p_to, p_sku, p_qty, v_moved_by, now());

    return v_current_qty - p_qty;
end;
$$ language plpgsql security definer;

